'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=file=>fs.readFileSync(path.join(root,file),'utf8');
const selector=read('docs/scifi-ui/scripts/formatx-reference-core-v26.js');
const productionBootstrap=read('docs/scifi-ui/scripts/formatx-core-real3d-v20.js');
const reference=read('docs/scifi-ui/scripts/formatx-reference-lock-v30.js');
const webgpu=read('docs/scifi-ui/scripts/formatx-webgpu-core-v29.js');
const webgl=read('docs/scifi-ui/scripts/formatx-orbital-core-v28.js');
const cinematic=read('docs/scifi-ui/scripts/formatx-cinematic-core-v27.js');
const entry=read('billing-worker/src/production-entry.js');
assert.match(selector,/const WEBGPU_PREVIEW = params\.get\('webgpu'\) === '1'/);
assert.match(selector,/production-v30-reference-lock-authority/);
assert.match(selector,/webgl2-v30-uploaded-reference-production/);
assert.match(productionBootstrap,/formatx-reference-lock-v30\.js\?v=20260810-uploaded-reference-lock-\d+/);
assert.match(productionBootstrap,/formatx-reference-lock-v30\.css\?v=20260810-uploaded-reference-lock-\d+/);
assert.match(reference,/organic-faceted-glass-r6/);
assert.match(reference,/for\(const k of\[3,6,9,R\]\)/);
assert.match(reference,/Math\.floor\(A\/8\)/);
assert.match(reference,/for\(const k of\[3,5,7,9\]\)/);
assert.match(reference,/branch=pow/);
assert.match(reference,/t=\.009/);
assert.ok(reference.includes('ready-v30'));
assert.doesNotMatch(selector,/if \(navigator\.gpu\)[\s\S]{0,500}webgpu-primary/);
assert.match(webgpu,/navigator\.gpu\.requestAdapter/);
assert.match(webgpu,/pass\.drawIndexed/);
assert.match(webgl,/canvas\.getContext\('webgl2'/);
assert.match(webgl,/gl\.drawElements\(gl\.TRIANGLES/);
assert.match(cinematic,/retired-by-orbital-v28/);
assert.match(entry,/formatx-reference-core-v26\.js/);
assert.doesNotMatch(reference,/new\s+Image\s*\(|drawImage\s*\(|THREE\b|three\.js/i);
console.log('PASS: organic-faceted v30 r6 remains the production authority; WebGPU v29 and WebGL2 v28 remain opt-in preview paths.');
